import jdk.jfr.consumer.*;import java.nio.file.*;import java.util.*;
class CryptJfr{public static void main(String[]a)throws Exception{var inc=new HashMap<String,Long>();var leaf=new HashMap<String,Long>();var threads=new HashMap<String,Long>();long n=0;try(var f=new RecordingFile(Path.of(a[0]))){while(f.hasMoreEvents()){var e=f.readEvent();if(!e.getEventType().getName().equals("jdk.ExecutionSample"))continue;n++;threads.merge(e.getThread("sampledThread").getJavaName(),1L,Long::sum);var st=e.getStackTrace();if(st==null)continue;var seen=new HashSet<String>();boolean first=true;for(var fr:st.getFrames()){String s=fr.getMethod().getType().getName()+"."+fr.getMethod().getName();if(first)leaf.merge(s,1L,Long::sum);first=false;if(seen.add(s))inc.merge(s,1L,Long::sum);}}}System.out.println("Samples "+n);for(var m:List.of(threads,leaf,inc)){System.out.println("----");m.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(45).forEach(System.out::println);}}}
